// =============================================================================
// UTILITY FUNCTIONS
// =============================================================================

/**
 * Creates a shadow style object with customizable parameters
 */
export const createShadow = (
  elevation: number = 5,
  shadowOpacity: number = 0.25,
  shadowRadius: number = 4,
  shadowColor: string = COLORS.shadowColor
) => ({
  shadowColor,
  shadowOffset: { width: 0, height: elevation / 2 },
  shadowOpacity,
  shadowRadius,
  elevation,
});

/**
 * Creates a button style with consistent theming
 */
export const createButtonStyle = (
  backgroundColor: string = COLORS.primaryOrange,
  textColor: string = COLORS.white,
  variant: "solid" | "outline" | "ghost" = "solid"
) => {
  const baseButton: ViewStyle = {
    alignItems: "center",
    justifyContent: "center",
    paddingHorizontal: SPACING.lg,
    paddingVertical: SPACING.md,
    borderRadius: BORDER_RADIUS.md,
    minHeight: SIZING.button.height,
  };

  const baseText: TextStyle = {
    fontFamily: TYPOGRAPHY.fontPrimary,
    fontSize: TYPOGRAPHY.fontSize.base,
    fontWeight: "400",
  };

  switch (variant) {
    case "outline":
      return {
        button: {
          ...baseButton,
          backgroundColor: COLORS.transparent,
          borderWidth: 2,
          borderColor: backgroundColor,
        },
        text: {
          ...baseText,
          color: backgroundColor,
        },
      };
    case "ghost":
      return {
        button: {
          ...baseButton,
          backgroundColor: COLORS.transparent,
        },
        text: {
          ...baseText,
          color: backgroundColor,
        },
      };
    default:
      return {
        button: {
          ...baseButton,
          backgroundColor,
          ...SHADOWS.sm,
        },
        text: {
          ...baseText,
          color: textColor,
        },
      };
  }
};

/**
 * Creates responsive padding based on device type
 */
export const createResponsivePadding = (basePadding: number = SPACING.md) => ({
  paddingHorizontal: basePadding,
  paddingVertical: basePadding * 0.75,
});

